<?php
require_once dirname(__DIR__,2).'/app/bootstrap.php';require_admin();
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$id=(int)($_POST['id']??0);$action=(string)($_POST['action']??'');if($id&&$action==='delete'){$s=db()->prepare('SELECT image_path FROM listings WHERE id=:id');$s->execute([':id'=>$id]);$img=$s->fetchColumn();db()->prepare('DELETE FROM listings WHERE id=:id')->execute([':id'=>$id]);delete_uploaded_image(is_string($img)?$img:null);flash('success','Listing deleted.');}elseif($id&&in_array($action,['publish','draft'],true)){db()->prepare('UPDATE listings SET status=:s,updated_at=CURRENT_TIMESTAMP WHERE id=:id')->execute([':s'=>$action==='publish'?'published':'draft',':id'=>$id]);flash('success',$action==='publish'?'Listing published.':'Listing moved to drafts.');}redirect(app_path('admin/listings.php'));}
$q=trim((string)($_GET['q']??''));$status=(string)($_GET['status']??'all');$where=[];$params=[];if($q!==''){$where[]='(name LIKE :q OR location LIKE :q OR category LIKE :q)';$params[':q']='%'.$q.'%';}if(in_array($status,['published','pending','draft'],true)){$where[]='status=:s';$params[':s']=$status;}$sql='SELECT * FROM listings'.($where?' WHERE '.implode(' AND ',$where):'').' ORDER BY updated_at DESC';$s=db()->prepare($sql);$s->execute($params);$rows=$s->fetchAll();$adminTitle='Listings';include __DIR__.'/_header.php';?>
<div class="admin-panel"><form class="admin-filter" method="get"><input type="search" name="q" value="<?= h($q) ?>" placeholder="Search name, category or area"><select name="status"><option value="all">All statuses</option><?php foreach(['published','pending','draft'] as $x): ?><option value="<?= $x ?>" <?= $status===$x?'selected':'' ?>><?= ucfirst($x) ?></option><?php endforeach; ?></select><button class="button button-dark button-small">Filter</button></form><div class="table-wrap"><table class="admin-table"><thead><tr><th>Business / place</th><th>Category</th><th>Area</th><th>Status</th><th>Updated</th><th>Actions</th></tr></thead><tbody><?php foreach($rows as $r): ?><tr><td><strong><?= h($r['name']) ?></strong><?php if((int)$r['is_demo']): ?><small>Sample seed content</small><?php endif; ?></td><td><?= h($r['category']) ?></td><td><?= h($r['location']) ?></td><td><span class="status-pill status-<?= h($r['status']) ?>"><?= h(ucfirst($r['status'])) ?></span></td><td><?= h(format_date($r['updated_at'])) ?></td><td><div class="row-actions"><a class="table-action" href="<?= app_path('admin/listing-form.php?id='.(int)$r['id']) ?>">Edit</a><?php if($r['status']!=='published'): ?><form method="post"><?= csrf_field() ?><input type="hidden" name="id" value="<?= (int)$r['id'] ?>"><input type="hidden" name="action" value="publish"><button class="table-action">Publish</button></form><?php else: ?><form method="post"><?= csrf_field() ?><input type="hidden" name="id" value="<?= (int)$r['id'] ?>"><input type="hidden" name="action" value="draft"><button class="table-action">Unpublish</button></form><?php endif; ?><form method="post" onsubmit="return confirm('Delete this listing permanently?')"><?= csrf_field() ?><input type="hidden" name="id" value="<?= (int)$r['id'] ?>"><input type="hidden" name="action" value="delete"><button class="table-action danger-text">Delete</button></form></div></td></tr><?php endforeach; ?><?php if(!$rows): ?><tr><td colspan="6" class="empty-admin">No matching listings found.</td></tr><?php endif; ?></tbody></table></div></div><?php include __DIR__.'/_footer.php';?>
